public partial class MigrationScene {
 StyleBoxFlat Style(Color bg,Color border,int thickness=1,int pad=10){var s=new StyleBoxFlat{BgColor=bg,BorderColor=border,CornerRadiusTopLeft=3,CornerRadiusTopRight=3,CornerRadiusBottomLeft=3,CornerRadiusBottomRight=3,ContentMarginLeft=pad,ContentMarginRight=pad,ContentMarginTop=pad,ContentMarginBottom=pad};s.SetBorderWidthAll(thickness);return s;}
 void InitTheme(){LoadInfoOptions();comicTheme=new Theme{DefaultFontSize=15};comicTheme.DefaultFont=new SystemFont{FontNames=new[]{"Bahnschrift","Segoe UI"}};comicTheme.SetColor("font_color","Label",new Color(.88f,.85f,.73f));comicTheme.SetColor("font_color","Button",new Color(.90f,.86f,.73f));comicTheme.SetStylebox("normal","Button",Style(new Color(.13f,.17f,.17f),new Color(.26f,.31f,.28f),1,11));comicTheme.SetStylebox("hover","Button",Style(new Color(.22f,.27f,.23f),new Color(.68f,.57f,.34f),2,11));comicTheme.SetStylebox("pressed","Button",Style(new Color(.29f,.30f,.21f),new Color(.80f,.67f,.40f),2,11));comicTheme.SetStylebox("focus","Button",Style(new Color(0,0,0,0),new Color(.67f,.58f,.37f),1,11));comicTheme.SetStylebox("panel","PanelContainer",Style(new Color(.055f,.075f,.078f,.97f),new Color(.53f,.45f,.30f),2,8));comicTheme.SetStylebox("background","ProgressBar",Style(new Color(.11f,.14f,.13f),new Color(.04f,.05f,.05f),1,0));comicTheme.SetStylebox("fill","ProgressBar",Style(new Color(.53f,.60f,.35f),new Color(.53f,.60f,.35f),0,0));comicTheme.SetStylebox("panel","LineEdit",Style(new Color(.09f,.12f,.12f),new Color(.35f,.39f,.32f),1,8));}
 Label HudLabel(int font=15){var l=new Label{MouseFilter=Control.MouseFilterEnum.Ignore};l.AddThemeFontSizeOverride("font_size",font);l.AddThemeColorOverride("font_shadow_color",new Color(.02f,.03f,.03f));l.AddThemeConstantOverride("shadow_offset_x",2);l.AddThemeConstantOverride("shadow_offset_y",2);hudRoot.AddChild(l);return l;}
 void NewHud(){InitTheme();ui=new CanvasLayer();AddChild(ui);hudRoot=new Control{MouseFilter=Control.MouseFilterEnum.Ignore,Theme=comicTheme};hudRoot.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);ui.AddChild(hudRoot);zoneLabel=HudLabel(22);clockLabel=HudLabel(14);hpLabel=HudLabel(14);needsLabel=HudLabel(13);ammoLabel=HudLabel(22);woundLabel=HudLabel(15);promptLabel=HudLabel(15);helpLabel=HudLabel(12);notice=HudLabel(14);hud=zoneLabel;hpBar=new ProgressBar{ShowPercentage=false,MouseFilter=Control.MouseFilterEnum.Ignore};staminaBar=new ProgressBar{ShowPercentage=false,MouseFilter=Control.MouseFilterEnum.Ignore};hudRoot.AddChild(hpBar);hudRoot.AddChild(staminaBar);damageTint=new ColorRect{Color=new Color(.55f,.1f,.05f,0),MouseFilter=Control.MouseFilterEnum.Ignore};damageTint.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);hudRoot.AddChild(damageTint);var crosshair=weaponCrosshair=new InkCrosshair{MouseFilter=Control.MouseFilterEnum.Ignore};crosshair.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);hudRoot.AddChild(crosshair);BuildHudFrame();hudRoot.MoveChild(crosshair,0);}
 void ComicHud(){PolishedHud();}
 string InteractionPrompt(){if(mountedBlueprint!=null)return "WASD / DRIVE / E DISMOUNT";if(!buildMode&&dungeon==null&&NearProp(2,4) is WorldProp car&&!game.World.Changes.Burned(car.Id))return "E / INSPECT AND RESTORE CAR";if(NearCommunity() is CampSurvivor friend)return "E / TALK TO "+friend.Name.ToUpperInvariant()+" / F7 COMMUNITY";if(NearbyPlayer() is CoopActor peer)return "E / PLAYER OPTIONS / "+peer.Name.ToUpperInvariant();if(AimedFurniture() is WorldProp furniture)return $"FURNITURE / {(ObjectHealth.TryGetValue(furniture.Id,out double furnitureHp)?furnitureHp:90):0}/90 HP / HIT WITH A WEAPON";var opening=AimedOpening();if(opening!=null&&opening.Def.Function=="door")return "E / "+(opening.Open?"CLOSE ":"OPEN ")+opening.Def.Name.ToUpperInvariant();if(HuntingPrompt()!="")return HuntingPrompt();if(FirstDayPrompt()!="")return FirstDayPrompt();if(InHeartRoom)return CampaignPrompt();if(ContentPrompt()!="")return ContentPrompt();if(LivingEnabled&&SettlementSitePrompt()!="")return SettlementSitePrompt();if(LivingEnabled&&RescueDogPrompt()!="")return RescueDogPrompt();if(LivingEnabled&&LivingPrompt()!="")return LivingPrompt();string campaign=CampaignPrompt();if(campaign!="")return campaign;if(NearEncounter()!=null)return "E / EXAMINE ABANDONED SCENE";if(NearDrone())return "E / DISTRESS DRONE";string crash=CrashPrompt();if(crash!="")return crash;string checkpoint=CheckpointPrompt();if(checkpoint!="")return checkpoint;string birthday=BirthdayPrompt();if(birthday!="")return birthday;string lastLetter=LetterPrompt();if(lastLetter!="")return lastLetter;string fever=FeverPrompt();if(fever!="")return fever;string woodland=WoodlandPrompt();if(woodland!="")return woodland;string family=FamilyPrompt();if(InFamilyRoom||family!="")return family;if(game.World.Changes.ScavengeAlarm is ScavengeAlarm alarm&&Distance(player.Position,alarm.Position)<3)return "E / SILENCE NOISE SOURCE";if(NearProp(12,3)!=null)return "E / READ LUMBER MILL WARNING";if(NearProp(13,4)!=null)return game.World.Changes.MillDefeated?"LUMBER MILL / CLEARED":"E / RING BELL / CHALLENGE THE FOREMAN";if(mountedBlueprint!=null)return "WASD / DRIVE / E DISMOUNT";var station=NearBlueprint();if(!buildMode&&station!=null)return "E / "+station.Def.Name.ToUpperInvariant();if(buildMode&&demolitionMode)return placement?.Reason??"DEMOLISH / aim at a structure";if(buildMode)return BuildDefinition.All[selectedBuild].Name.ToUpper()+"  /  "+(placement==null?"Aim at a surface":placement.Reason);if(dungeon!=null){if(Distance(player.Position,new Vector3(0,0,3))<2)return "E  /  RETURN TO SURFACE";for(int i=0;i<3;i++)if(Distance(player.Position,new Vector3((float)ExpeditionDungeon.ChestX[i],0,(float)ExpeditionDungeon.ChestZ[i]))<2.5)return Guarded(ExpeditionDungeon.ChestX[i],ExpeditionDungeon.ChestZ[i],8)?"CHEST GUARDED  /  CLEAR INFECTED":"E  /  SEARCH RELIC CHEST";if(dungeon.Tier==4&&Distance(player.Position,new Vector3(0,0,-26))<2.2)return "E  /  DESCEND TO ISOLATION WARD";if(dungeon.Deep&&Distance(player.Position,new Vector3(5,0,-22))<2.4)return "E  /  RECOVER BIOALLOY";for(int i=0;i<3;i++)if(Distance(player.Position,dungeonRecords[i])<2.5)return "E  /  READ ABANDONED RECORD";return "";}foreach(var d in ExpeditionDungeon.Nearby(game.World,0,0))if(Distance(player.Position,Ground(d.X,d.Z))<3.5)return "E  /  ENTER "+d.Name;foreach(var well in game.World.Changes.Wells)if(ExpeditionGame.Distance(player.Position.X,player.Position.Z,well.X,well.Z)<2.3)return "E  /  DRAW UNTREATED WATER";if(NearProp(10,2.8f)!=null)return "E  /  OPEN WORKTABLE";if(NearProp(15,2.6f) is WorldProp salvage)return "E / SEARCH "+SalvageNames[salvage.Material].ToUpperInvariant();if(NearProp(9,2.6f)!=null)return "E  /  SEARCH SUPPLIES";var resource=NearProp(1,3);if(resource!=null)return "E  /  GATHER "+ExpeditionGame.ResourceNames[resource.Material].ToUpper();if(NearProp(0)!=null)return axeEquipped?"LEFT CLICK / AIM AT TRUNK / SWING":"T / EQUIP CHOPPING AXE";if(NearProp(2,4)!=null||NearProp(8,4)!=null)return "E  /  READ ABANDONED NOTE";return ObjectConditionPrompt();}
}
internal partial class InkCrosshair:Control {
 public float Spread;public bool Scoped;
 public override void _Draw(){var p=Size*.5f;if(Scoped){float radius=Size.Y*.43f;for(int i=0;i<96;i++){float a=i*Mathf.Tau/96,b=(i+1)*Mathf.Tau/96;var A=new Vector2(Mathf.Cos(a),Mathf.Sin(a));var B=new Vector2(Mathf.Cos(b),Mathf.Sin(b));DrawColoredPolygon(new[]{p+A*radius,p+B*radius,p+B*Size.X*2,p+A*Size.X*2},new Color(.015f,.02f,.018f,.97f));}DrawArc(p,radius,0,Mathf.Tau,96,new(.12f,.13f,.11f),6,true);DrawLine(p-Vector2.Right*radius,p+Vector2.Right*radius,new(.04f,.04f,.03f),1);DrawLine(p-Vector2.Down*radius,p+Vector2.Down*radius,new(.04f,.04f,.03f),1);for(int j=-4;j<=4;j++)if(j!=0)DrawLine(p+new Vector2(j*24,-4),p+new Vector2(j*24,4),new(.04f,.04f,.03f),1);DrawCircle(p,2,new(.7f,.2f,.08f));return;}foreach(var d in new[]{Vector2.Up,Vector2.Down,Vector2.Left,Vector2.Right}){DrawLine(p+d*(4+Spread),p+d*(10+Spread),new Color(.04f,.05f,.05f),3);DrawLine(p+d*(4+Spread),p+d*(9+Spread),new Color(.87f,.86f,.72f),1);}}
}
